CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner' CHECK(role='owner'));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=auth.uid() AND u.email_confirmed_at IS NOT NULL AND lower(u.email)='mbalenhlemotaung923@gmail.com') $$;
REVOKE ALL ON FUNCTION public.is_owner() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_owner() TO authenticated;
CREATE FUNCTION public.assign_business_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='mbalenhlemotaung923@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER braiding_owner AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_business_owner();
CREATE TABLE public.services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150), price integer NOT NULL CHECK(price>=0), image_index integer NOT NULL DEFAULT 0 CHECK(image_index BETWEEN 0 AND 3), active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.services TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated; GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_services ON public.services FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY owner_services ON public.services FOR ALL TO authenticated USING(public.is_owner()) WITH CHECK(public.is_owner());
CREATE TABLE public.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 150), description text NOT NULL DEFAULT '' CHECK(length(description)<=2000), category text NOT NULL DEFAULT 'Personal Tasks', due_date date, priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('High','Medium','Low')), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','In Progress','Completed')), sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_tasks ON public.tasks FOR ALL TO authenticated USING(public.is_owner()) WITH CHECK(public.is_owner());
CREATE TABLE public.appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_name text NOT NULL CHECK(length(customer_name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(phone ~ '^\+?[0-9]{10,15}$'), service_id uuid NOT NULL REFERENCES public.services(id), appointment_date date NOT NULL, appointment_time time NOT NULL, hair_length text NOT NULL DEFAULT 'Normal' CHECK(length(hair_length)<=100), requirements text NOT NULL DEFAULT '' CHECK(length(requirements)<=2000), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000), house_call boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Confirmed','Completed','Cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_appointments ON public.appointments FOR ALL TO authenticated USING(public.is_owner()) WITH CHECK(public.is_owner());
CREATE UNIQUE INDEX appointment_slot ON public.appointments(appointment_date,appointment_time) WHERE status <> 'Cancelled';
CREATE FUNCTION public.request_booking(p_name text,p_phone text,p_service uuid,p_date date,p_time time,p_length text,p_requirements text,p_notes text,p_house boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF p_date < (now() AT TIME ZONE 'Africa/Johannesburg')::date THEN RAISE EXCEPTION 'Please select a future date'; END IF; IF NOT EXISTS(SELECT 1 FROM public.services WHERE id=p_service AND active) THEN RAISE EXCEPTION 'Style is unavailable'; END IF; INSERT INTO public.appointments(customer_name,phone,service_id,appointment_date,appointment_time,hair_length,requirements,notes,house_call) VALUES(trim(p_name),p_phone,p_service,p_date,p_time,p_length,p_requirements,p_notes,p_house) RETURNING id INTO result; RETURN result; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'That time already has a booking. Please choose another time.'; END $$;
REVOKE ALL ON FUNCTION public.request_booking(text,text,uuid,date,time,text,text,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_booking(text,text,uuid,date,time,text,text,text,boolean) TO anon,authenticated;